use std::time::Instant;
use wasmtime::{Collector, Config, Engine, Linker, Module, OptLevel, Store, Strategy, Val};

fn main() -> wasmtime::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let input = std::fs::read(&args[1])?;
    let mut config = Config::new();
    config.strategy(Strategy::Cranelift);
    config.cranelift_opt_level(OptLevel::Speed);
    config.collector(Collector::Copying);
    config.parallel_compilation(false);
    // No cache feature is linked. Read/engine setup are outside compilation.
    let t = Instant::now();
    let engine = Engine::new(&config)?;
    let engine_setup = t.elapsed().as_secs_f64();
    let t = Instant::now();
    let module = if args.iter().any(|a| a == "--artifact") {
        // Only our just-produced, trusted local compatibility-control artifact.
        unsafe { Module::deserialize(&engine, &input)? }
    } else {
        Module::new(&engine, &input)?
    };
    let compile_or_load = t.elapsed().as_secs_f64();
    if let Some(index) = args.iter().position(|a| a == "--emit") {
        std::fs::write(&args[index + 1], module.serialize()?)?;
    }
    let t = Instant::now();
    let mut store = Store::new(&engine, ());
    let linker = Linker::<()>::new(&engine);
    let instance = futures::executor::block_on(linker.instantiate_async(&mut store, &module))?;
    let instantiate = t.elapsed().as_secs_f64();
    let func = instance.get_func(&mut store, "probe").expect("missing probe");
    let mut results = [Val::I32(0)];
    let t = Instant::now();
    futures::executor::block_on(func.call_async(&mut store, &[], &mut results))?;
    let invoke = t.elapsed().as_secs_f64();
    assert_eq!(results[0].i32(), Some(1), "guest assertions did not pass");
    println!("{{\"engine_setup\":{engine_setup:.9},\"compile_or_load\":{compile_or_load:.9},\"instantiate_including_start\":{instantiate:.9},\"invoke\":{invoke:.9},\"result\":1}}");
    Ok(())
}
